ee:message.ee:set-payload:
%dw 2.0
output application/json
---
{
  error: {
    code: "VALIDATION_ERROR",
    message: "Request validation failed.",
    correlationId: correlationId,
    details: vars.errorDetails
  }
}

%dw 2.0
output application/json
---
{
  error: {
    code: "CUSTOMER_NOT_FOUND",
    message: "Customer " ++ vars.customerId ++ " was not found.",
    correlationId: correlationId
  }
}

%dw 2.0
output application/json
---
{
  error: {
    code: "DOWNSTREAM_TIMEOUT",
    message: "The customer backend did not respond within the configured timeout.",
    correlationId: correlationId
  }
}

%dw 2.0
output application/json
---
{
  error: {
    code: "RATE_LIMITED",
    message: "Too many requests. Please try again later.",
    correlationId: correlationId
  }
}

%dw 2.0
output application/json
---
{
  error: {
    code: "DOWNSTREAM_SERVICE_ERROR",
    message: "The customer backend returned an error.",
    correlationId: correlationId
  }
}

%dw 2.0
output application/json
---
{
  error: {
    code: "INTERNAL_ERROR",
    message: "An unexpected error occurred.",
    correlationId: correlationId
  }
}
